import{c as l,Q as a,j as e,m as i}from"./chunks/framework.DOi4mjdC.js";const s="/assets/zh-cn_image_0000002375339736.D2_QQLbm.png",o="/assets/zh-cn_image_0000002375340188.DiY0ORbc.png",n="/assets/%E5%BC%80%E5%90%AF%E5%A4%9A%E6%A0%B8%E5%88%87K.DiSWwRI6.png",p="/assets/zh-cn_image_0000002408742265.jtkmDe3y.png",u="/assets/zh-cn_image_0000002375184084.CzJBV_mt.png",_=JSON.parse('{"title":"Matmul高阶API使能多核切K","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能多核切K","slug":"matmul高阶api使能多核切k"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能多核切K.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能多核切K.md"}'),r={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能多核切K.md"};function g(c,t,d,h,m,q){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="matmul高阶api使能多核切k" tabindex="-1">Matmul高阶API使能多核切K <a class="header-anchor" href="#matmul高阶api使能多核切k" aria-label="Permalink to &quot;Matmul高阶API使能多核切K&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，使能多核切K功能对算子性能的提升效果**。**为了实现算子在多核上并行执行，提升计算效率，需要将矩阵数据进行切分，切分后的数据块被分配到不同的核上处理。通常情况下，切分矩阵数据时仅切分M、N轴，不切分K轴。若M和N较小，切分M和N轴较困难，此时需要考虑K轴切分；使能多核切K功能后，该场景下可以对矩阵的K轴进行切分，从而使算子在多核上并行执行。由于K轴较大，在该场景下不切分K轴通常会导致单核的输入数据量过大，使能K轴切分后，切分策略能够更有效地平衡输出带宽和输入带宽。</p><ul><li><p>使能多核切K的适用场景</p><ul><li>矩阵的K轴较大，M轴和N轴相比K轴较小，可以在K轴进行切分，使算子并行执行的核数更多。</li><li>矩阵的M轴、N轴和K轴均较大时，可以在K轴进行切分，使切分策略更好地平衡输入和输出带宽。</li></ul></li><li><p>使能多核切K的约束条件</p><ul><li>使能多核切K的场景，获取C矩阵结果时仅支持输出到Global Memory。</li><li>使能多核切K的场景，需在Kernel侧代码中首次将C矩阵分片的结果写入Global Memory之前，先对Global Memory进行清零，在获取C矩阵分片的结果时，开启AtomicAdd累加。如果不预先清零Global Memory，可能会因为累加Global Memory中的原始无效数据而产生精度问题。</li><li>使能多核切K的场景，不支持Bias参与矩阵乘计算。</li></ul></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;16, 1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;1024, 16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，算子中使能高阶API Matmul的纯Cube模式。Tiling参数如下：</p><ul><li>原始shape：M=16, N= 16, K=1024。</li><li>单核shape：未开启多核切K时，singleCoreM=16，singleCoreN=16，singleCoreK=1024；开启多核切K后，singleCoreM=16，singleCoreN=16，singleCoreK=512。</li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的流水图如下，由于未使能多核切K，且M和N非常小，原始矩阵数据未进行切分，所有数据在单核上进行计算。<img src="'+s+'" alt=""></p></li><li><p>优化前的Profiling数据如下，可以看到算子只在单核上执行，aic_time耗时约19.60us，其中aic_mte2_time的平均耗时约为13.72us，aic_mte2_ratio占比较高。</p><p><img src="'+o+'" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>使能多核切K后，矩阵的K方向数据可以进行切分。如下图所示，C矩阵中的R矩阵块，是通过A1*B1+A2*B2+A3*B3累加得到的，其中，A1*B1、A2*B2、A3*B3可在多个核上并行计算。</p><p><strong>图 1</strong> 开启多核切K<br><img src="'+n+`" alt="" title="开启多核切K"></p><p>使能多核切K功能的方式为：在GetTiling接口前调用EnableMultiCoreSplitK接口，使能多核切K，并在Kernel实现中，对C矩阵的Global Memory地址清零后开启AtomicAdd。使能多核切K的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_splitk" target="_blank" rel="noreferrer">多核切K场景的算子样例</a>。具体步骤如下：</p><ul><li><p>Tiling实现</p><p>通过GetTiling接口获取TCubeTiling结构体前，调用EnableMultiCoreSplitK接口且入参为true，使能多核切K。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cubeTiling.SetOrgShape(M, N, K);</span></span>
<span class="line"><span>cubeTiling.SetShape(M, N, K);</span></span>
<span class="line"><span>cubeTiling.EnableBias(isBias);</span></span>
<span class="line"><span>cubeTiling.SetBufferSpace(-1, -1, -1);</span></span>
<span class="line"><span>// tiling enable split K</span></span>
<span class="line"><span>cubeTiling.EnableMultiCoreSplitK(true);</span></span>
<span class="line"><span>if (cubeTiling.GetTiling(tilingData) == -1) {</span></span>
<span class="line"><span>    std::cout &lt;&lt; &quot;gen tiling failed.&quot; &lt;&lt; std::endl;</span></span>
<span class="line"><span>    return {};</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Kernel实现</p><p>调用Fill接口，对C矩阵的Global Memory地址清零。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ cType*&gt;(c), tiling.M * tiling.N);</span></span>
<span class="line"><span>// clear gm</span></span>
<span class="line"><span>Fill(cGlobal, tiling.M * tiling.N, (cType)0);</span></span></code></pre></div><p>调用IterateAll接口，开启AtomicAdd累加，完成矩阵乘操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// set AtomicAdd</span></span>
<span class="line"><span>uint8_t enAtomic = 1;</span></span>
<span class="line"><span>matmulObj.IterateAll(cGlobal, enAtomic);</span></span></code></pre></div></li></ul><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的流水图如下，开启多核切K后，切分原始矩阵的K方向，单核处理K方向的数据量由原来的1024变为512，单核处理的数据量减半，MTE2流水变短。</p><p><img src="`+p+'" alt=""></p></li><li><p>优化后的Profiling数据如下，可以看到算子在两个核上执行，aic_time平均耗时约为13.70us，较优化前的19.60us有较大提升。<img src="'+u+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>当算子使用Matmul API完成矩阵计算时，原始矩阵的M和N方向无法进行有效切分，且结果输出到Global Memory时，可以考虑使能多核切K功能，实现多核并行，提升计算效率。</p>',22)])])}const K=l(r,[["render",g]]);export{_ as __pageData,K as default};
